import sys
from collections import defaultdict

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    q = int(data[1])

    parents = [0] + list(map(int, data[2:n+1]))
    queries = [(int(data[n+2+i*2]), int(data[n+3+i*2])) for i in range(q)]

    # Build the tree
    tree = defaultdict(list)
    for i in range(2, n+1):
        tree[parents[i]].append(i)

    # Precompute the DFS order for each node
    def dfs(node, parent, order):
        order.append(node)
        for child in sorted(tree[node]):
            if child != parent:
                dfs(child, node, order)

    dfs_order = [[] for _ in range(n+1)]
    for i in range(1, n+1):
        dfs(i, -1, dfs_order[i])

    # Process each query
    results = []
    for u, k in queries:
        if k > len(dfs_order[u]):
            results.append(-1)
        else:
            results.append(dfs_order[u][k-1])

    # Output the results
    print("\n".join(map(str, results)))

if __name__ == "__main__":
